-- Lan–dados manawi– Yéhuwah–nglebetaken–panjenengan Yéhuwah dhateng– tanah tiyang–Kanaan lan–tiyang–Hèt lan–tiyang–Amori lan–tiyang–Hewi lan–tiyang–Yebus ingkang Panjenenganipun–sampun–sumpah dhateng–para–leluhur–panjenengan kangge–maringi dhateng–panjenengan tanah ingkang–mili susu lan–madu lan–panjenengan–ngabekti – pangibadah punika ing–wulan punika

BEGIN;
-- 0201300501: וְהָיָ֣ה (H1961) → "Lan–dados" [opus-4.5-chirho]
WITH np AS (
  INSERT INTO phrase (language_id, created_at)
  SELECT (SELECT id FROM language WHERE code = 'jav'), NOW()
  WHERE NOT EXISTS (
    SELECT 1 FROM phrase p JOIN phrase_word pw ON pw.phrase_id = p.id
    WHERE pw.word_id = '0201300501' AND p.language_id = (SELECT id FROM language WHERE code = 'jav') AND p.deleted_at IS NULL
  )
  RETURNING id
)
INSERT INTO phrase_word (phrase_id, word_id) SELECT id, '0201300501' FROM np ON CONFLICT DO NOTHING;
INSERT INTO gloss (phrase_id, gloss, state, updated_at, source)
SELECT p.id, 'Lan–dados', 'UNAPPROVED', NOW(), 'IMPORT'
FROM phrase p JOIN phrase_word pw ON pw.phrase_id = p.id
WHERE pw.word_id = '0201300501' AND p.language_id = (SELECT id FROM language WHERE code = 'jav') AND p.deleted_at IS NULL
ON CONFLICT (phrase_id) DO UPDATE SET gloss = EXCLUDED.gloss, updated_at = EXCLUDED.updated_at, source = EXCLUDED.source;
